export function resolveItemShopName(itemName: string): string | null {
  if (!itemName) return null;
  const direct = MASTER_ITEM_MAPPING[itemName];
  if (direct) return direct.shopName;
  return null;
}

export function resolveItemCategoryCode(itemName: string): string | null {
  if (!itemName) return null;
  const direct = MASTER_ITEM_MAPPING[itemName];
  if (direct) return direct.categoryCode;
  return null;
}